<script setup lang="ts">
import PageNotice from '../components/PageNotice.vue';
import ScrollTable from '../components/ScrollTable.vue';
import {computed,onMounted,reactive,ref} from 'vue';import {useI18n} from 'vue-i18n';import {session} from '../services/api';import {listMembers,createMember,changeMemberStatus,changeProviderRole,changeProviderAuthorization,type Member} from '../services/operations';import OperationsError from '../components/operations/OperationsError.vue';
const success=ref(false),successRun=ref(0);
const {t}=useI18n();const members=ref<Member[]>([]),selected=ref<Member|null>(null),offset=ref(0),busy=ref(false),error=ref<unknown>(null),query=ref(''),drawer=ref(false),createDialog=ref(false),action=ref<'disable'|'enable'|'grantRole'|'revokeRole'|'grant'|'revoke'|null>(null),note=ref(''),validation=ref(''),validationRun=ref(0);const form=reactive({display_name:'',email:'',password:'',ui_locale:'ja' as 'zh'|'ja'});const canManage=computed(()=>session.account?.roles.includes('administrator'));const rows=computed(()=>members.value.filter(m=>`${m.id} ${m.display_name} ${m.email}`.toLowerCase().includes(query.value.trim().toLowerCase())));const columns=computed(()=>[{colKey:'name',title:t('ops.members.member'),width:230},{colKey:'status',title:t('ops.members.account'),width:100},{colKey:'roles',title:t('ops.api.roles')},{colKey:'auth',title:t('ops.members.auth'),width:110}]);
async function load(){busy.value=true;error.value=null;try{members.value=(await listMembers(offset.value)).items;selected.value=members.value.find(m=>m.id===selected.value?.id)??null}catch(e){error.value=e;members.value=[];selected.value=null}finally{busy.value=false}}
function select(member:Member){selected.value=member;drawer.value=true;note.value='';validation.value=''}
function ask(value:NonNullable<typeof action.value>){success.value=false;++validationRun.value;validation.value='';if(!note.value.trim()){validation.value=t('ops.api.errors.reasonRequired');return}action.value=value}
async function update(){if(!selected.value||!action.value)return;success.value=false;busy.value=true;error.value=null;try{const m=selected.value;if(action.value==='disable'||action.value==='enable'){await changeMemberStatus(m.id,m.row_version,action.value==='disable'?'disabled':'active',note.value)}else if(action.value==='grantRole'||action.value==='revokeRole'){await changeProviderRole(m.id,action.value==='grantRole',note.value)}else{await changeProviderAuthorization(m.id,action.value==='grant',note.value)}action.value=null;note.value='';success.value=true;++successRun.value;await load()}catch(e){error.value=e;action.value=null}finally{busy.value=false}}
function openCreate(){Object.assign(form,{display_name:'',email:'',password:'',ui_locale:'ja'});validation.value='';createDialog.value=true}
async function create(){success.value=false;++validationRun.value;validation.value='';if(!form.display_name.trim()||!/^\S+@\S+\.\S+$/.test(form.email)||form.password.length<12){validation.value=t('ops.api.createError');return}busy.value=true;error.value=null;try{await createMember({...form,display_name:form.display_name.trim(),email:form.email.trim()});createDialog.value=false;form.password='';offset.value=0;await load();success.value=true;++successRun.value}catch(e){error.value=e}finally{busy.value=false}}
function closeCreate(){createDialog.value=false;form.password=''}
onMounted(load);
</script>
<template><div class="page-stack module-page"><OperationsError :error="error"/><PageNotice v-if="success" :key="successRun" theme="success" :message="t('ops.api.saved')" @close="success=false"/><PageNotice v-if="!canManage" theme="warning" :message="t('ops.api.forbidden')"/><t-card :title="t('ops.members.title')" :bordered="false" class="section-card list-card"><div class="table-toolbar"><t-input v-model="query" :placeholder="t('ops.keyword')" clearable style="max-width:360px"/><PageNotice notification theme="info" :message="t('ops.api.pageFilter')"/><t-button :loading="busy" variant="outline" @click="load">{{t('ops.api.refresh')}}</t-button><t-button v-if="canManage" @click="openCreate">{{t('ops.api.create')}}</t-button></div><ScrollTable row-key="id" :data="rows" :columns="columns" :empty="t('ops.api.empty')" hover><template #name="{row}"><t-link theme="primary" @click="select(row)">{{row.display_name}}</t-link><p class="muted">{{row.email}}</p><small class="mono">{{row.id}}</small></template><template #status="{row}"><t-tag :theme="row.status==='active'?'success':'default'" variant="light">{{t(`ops.api.status.${row.status}`)}}</t-tag></template><template #roles="{row}"><t-space break-line><t-tag v-for="role in row.roles" :key="role" variant="light">{{role}}</t-tag><span v-if="!row.roles.length">—</span></t-space></template><template #auth="{row}"><t-tag :theme="row.internally_authorized?'primary':'default'" variant="light">{{t(`ops.states.${row.internally_authorized?'authorized':'unauthorized'}`)}}</t-tag></template></ScrollTable><div class="pager"><t-button :disabled="offset===0||busy" variant="outline" @click="offset-=20;load()">{{t('ops.api.previous')}}</t-button><span>{{t('ops.api.page',{page:offset/20+1})}}</span><t-button :disabled="members.length<20||busy" variant="outline" @click="offset+=20;load()">{{t('ops.api.next')}}</t-button></div></t-card><PageNotice notification theme="info" :message="t('ops.members.certificationHint')"/>
<t-drawer v-model:visible="drawer" :header="t('ops.members.detail')" :close-btn="true" :footer="false" size="540px"><div v-if="selected" class="page-stack"><OperationsError :error="error" inline/><PageNotice inline theme="info" :message="t('ops.api.noOngoing')"/><PageNotice inline v-if="selected.id===session.account?.id" theme="info" :message="t('ops.api.self')"/><PageNotice inline theme="warning" :message="t('ops.api.memberHint')"/><PageNotice inline v-if="validation" :key="validationRun" theme="error" :message="validation"/><strong>{{selected.display_name}}</strong><p>{{selected.email}}</p><t-descriptions :column="1"><t-descriptions-item :label="t('ops.members.account')">{{t(`ops.api.status.${selected.status}`)}}</t-descriptions-item><t-descriptions-item :label="t('ops.api.rowVersion')">{{selected.row_version}}</t-descriptions-item><t-descriptions-item :label="t('ops.members.certified')">{{t('ops.states.unverified')}}</t-descriptions-item></t-descriptions><template v-if="selected.id!==session.account?.id&&canManage"><label>{{t('ops.api.reason')}}</label><t-textarea v-model="note" :maxlength="2000" :autosize="{minRows:3,maxRows:7}"/><t-space break-line><t-button :disabled="busy" :theme="selected.status==='active'?'danger':'primary'" variant="outline" @click="ask(selected.status==='active'?'disable':'enable')">{{t(`ops.api.${selected.status==='active'?'disable':'enable'}`)}}</t-button><t-button :disabled="busy" variant="outline" @click="ask(selected.roles.includes('provider')?'revokeRole':'grantRole')">{{t(`ops.api.${selected.roles.includes('provider')?'revokeRole':'grantRole'}`)}}</t-button><t-button :disabled="busy||(!selected.internally_authorized&&(selected.status!=='active'||!selected.roles.includes('provider')))" variant="outline" @click="ask(selected.internally_authorized?'revoke':'grant')">{{t(`ops.api.${selected.internally_authorized?'revoke':'grant'}`)}}</t-button></t-space></template></div></t-drawer>
<t-dialog :visible="action!==null" :header="action?t(`ops.api.${action}`):''" :confirm-btn="{content:t('ops.confirm'),loading:busy}" :cancel-btn="t('ops.cancel')" @close="action=null" @confirm="update"><PageNotice inline theme="info" :message="t('ops.api.confirmWrite')"/><p>{{selected?.display_name}} · {{selected?.email}}</p><p class="readable">{{note}}</p></t-dialog>
<t-dialog :visible="createDialog" :header="t('ops.api.create')" :confirm-btn="{content:t('ops.confirm'),loading:busy}" :cancel-btn="t('ops.cancel')" @close="closeCreate" @confirm="create"><div class="page-stack"><OperationsError :error="error" inline/><PageNotice inline v-if="validation" :key="validationRun" theme="error" :message="validation"/><PageNotice inline theme="info" :message="t('ops.api.createHint')"/><t-form label-align="top"><t-form-item :label="t('ops.members.name')" required-mark><t-input v-model="form.display_name" :maxlength="80"/></t-form-item><t-form-item :label="t('ops.members.email')" required-mark><t-input v-model="form.email" :maxlength="160"/></t-form-item><t-form-item :label="t('ops.api.password')" :help="t('ops.api.passwordHint')" required-mark><t-input v-model="form.password" type="password" autocomplete="new-password" :maxlength="128"/></t-form-item></t-form></div></t-dialog></div></template>
<style scoped>.pager{display:flex;align-items:center;justify-content:flex-end;gap:16px;margin-top:24px}.mono{overflow-wrap:anywhere}</style>
